CREATE TABLE IF NOT EXISTS gis_phase347_crosswalk_repair (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), crosswalk_version TEXT NOT NULL, audit_id UUID NOT NULL, candidate_id UUID NOT NULL, source_feature_id UUID NOT NULL, target_feature_id UUID NOT NULL, repair_score DOUBLE PRECISION NOT NULL DEFAULT 0, repair_status TEXT NOT NULL DEFAULT 'REVIEW', rationale JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(crosswalk_version,candidate_id));